'use strict';
const{test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),vm=require('node:vm'),{execFileSync}=require('node:child_process'),{parse}=require('../audits/audit-i18n-global.cjs');
const root=path.resolve(__dirname,'../..'),assets=process.env.GOULAG_DESCRIPTIONS_ASSET_DIR||root,read=f=>fs.readFileSync(path.join(assets,f),'utf8'),proof=JSON.parse(fs.readFileSync(path.join(root,'outils/audits/I18N-GOULAG-DESCRIPTIONS-20261116-preuve.json'))),langs=['fr','en','es','zh-TW','ru','ko','ar','pt-BR','de'];
const snapshot=(sha,f)=>execFileSync('git',['show',sha+':'+f],{cwd:root,encoding:'utf8',maxBuffer:5e6}),old=f=>snapshot(proof.baseCommit,f),rows=s=>[...s.matchAll(/^\s*\[("[^\n]+")\],?$/gm)].map(m=>JSON.parse('['+m[1]+']'));
function fn(s,name){const n=parse(s).body.find(n=>n.type==='FunctionDeclaration'&&n.id.name===name);assert.ok(n,name);return s.slice(n.start,n.end);}
function api(s,lang,country='soviet',enabled=true){const c={state:{country},RP_I18N_GAME_ENABLED:enabled,RPPlateauI18n:{language:()=>lang}};c.window=c;vm.createContext(c);vm.runInContext(s,c);return c.RPSovarkaDescI18n;}
test('cinq descriptions françaises déjà présentes, 40 traductions ajoutées, anciennes lignes intactes et repli exact',()=>{
 const b=rows(old('i18n/sovarka-descriptions-resources.js')),a=rows(snapshot(proof.codeCommit,'i18n/sovarka-descriptions-resources.js')),current=rows(read('i18n/sovarka-descriptions-resources.js'));assert.deepEqual(a.slice(0,b.length),b);assert.equal(a.length,b.length+5);assert.deepEqual(a.slice(b.length).map(r=>r[0]),proof.rooms.map(r=>r.fr));
 const c={};vm.createContext(c);vm.runInContext(old('data.js')+';this.W=WORLD;',c);
 for(const [i,r]of proof.rooms.entries()){const ctx=c.W.soviet.qhs.buildingContext['qhs-prison'];assert.equal((ctx.roomOverrides[r.id]||ctx.roomsExtra[r.id]).desc,r.fr);const line=current.find(x=>x[0]===r.fr);assert.ok(line);assert.equal(line.length,9);for(const[j,l]of langs.entries()){assert.ok(line[j].trim());if(j)assert.notEqual(line[j],r.fr);assert.equal(api(read('i18n/sovarka-descriptions-resources.js'),l).desc(r.fr),line[j]);assert.equal(api(read('i18n/sovarka-descriptions-resources.js'),l,'republic').desc(r.fr),r.fr);}assert.equal(api(read('i18n/sovarka-descriptions-resources.js'),'en','soviet',false).desc(r.fr),r.fr);}
 const first=current.find(r=>r[0]===proof.rooms[0].fr),missing=read('i18n/sovarka-descriptions-resources.js').replace(JSON.stringify(first[8]),'""');assert.notEqual(missing,read('i18n/sovarka-descriptions-resources.js'));assert.equal(api(missing,'de').desc(first[0]),first[0]);assert.equal(api(read('i18n/sovarka-descriptions-resources.js'),'unknown').desc(first[0]),first[0]);assert.equal(api(read('i18n/sovarka-descriptions-resources.js'),'ar').desc('Texte joueur <opaque>'),'Texte joueur <opaque>');
});
test('aucune mécanique, donnée, API, migration, navigation ou style modifié ; seul cache de catalogue dans le HTML',()=>{
 const names=execFileSync('git',['diff','--name-only',proof.baseCommit,proof.codeCommit],{cwd:root,encoding:'utf8'}).trim().split('\n');assert.deepEqual(names.filter(f=>!['RELAIS.md','plateau.html','i18n/sovarka-descriptions-resources.js','i18n/packed/sovarka-descriptions-resources.js.br','outils/audits/I18N-CATALOGUES-TRANSPORT.json'].includes(f)),[]);
 for(const f of ['data.js','plateau-navigation.js','plateau-core.js','plateau-politique.js','plateau-router.js','style.css','i18n/plateau-init.js'])assert.equal(snapshot(proof.codeCommit,f),old(f),f);
 const norm=s=>s.replace(/sovarka-descriptions-resources\.js\?v=[^"]+/g,'sovarka-descriptions-resources.js?v=VERSION');assert.equal(norm(snapshot(proof.codeCommit,'plateau.html')),norm(old('plateau.html')));
 const strip=s=>s.replace(/const L=\[[\s\S]*?\n \];/,'const L=[];');assert.equal(strip(snapshot(proof.codeCommit,'i18n/sovarka-descriptions-resources.js')),strip(old('i18n/sovarka-descriptions-resources.js')));
});
test('références générées exactes : seul le goulag resynchronisé, migrations et données canoniques intactes',()=>{
 const local=f=>fs.readFileSync(path.join(root,f),'utf8'),table=s=>JSON.parse(s.slice(s.indexOf('{'),s.lastIndexOf('}')+1));
 const before=table(old('api/_pnj-scenes-generes.js')),after=table(snapshot(proof.maintenanceCommit,'api/_pnj-scenes-generes.js')),scope=k=>JSON.parse(k).slice(0,3).join('/')==='soviet/qhs/qhs-prison';
 assert.deepEqual(Object.fromEntries(Object.entries(after).filter(([k])=>!scope(k))),Object.fromEntries(Object.entries(before).filter(([k])=>!scope(k))));
 const camp=Object.entries(after).filter(([k])=>scope(k));assert.deepEqual(camp.map(([k])=>JSON.parse(k)[3]).sort(),proof.rooms.map(r=>r.id).sort());for(const[,room]of camp)assert.deepEqual(room.personnes,[]);
 assert.equal(execFileSync(process.execPath,['outils/generateurs/generer-pnj-lieux-metiers.cjs','--scenes-js'],{cwd:root,encoding:'utf8',maxBuffer:5e6}),local('api/_pnj-scenes-generes.js'));
 assert.match(execFileSync(process.execPath,['outils/generateurs/navigation-lieux.cjs','--verifier'],{cwd:root,encoding:'utf8'}),/284 bâtiments conformes/);
 const changed=execFileSync('git',['diff','--name-only',proof.baseCommit,proof.maintenanceCommit],{cwd:root,encoding:'utf8'}).split('\n');assert.equal(changed.some(f=>f.startsWith('migrations/')||f==='data.js'||f==='api/chat.js'),false);
});
test('Chromium : rendu réel des cinq pièces, neuf langues, Républia isolée, 320/390/1280, RTL et aucune requête/dépense par bascule',async()=>{
 const{chromium}=require('playwright'),browser=await chromium.launch({headless:true,executablePath:process.env.CHROMIUM_PATH||'/usr/bin/chromium',args:['--no-sandbox']});let switches=0;
 const nav=read('plateau-navigation.js'),renderStart=nav.indexOf('  const descBase = roomOverride?.desc'),renderEnd=nav.indexOf('  const ROOMS_AVEC_CAISSE_SPECIFIQUE',renderStart);assert.ok(renderStart>0&&renderEnd>renderStart);const fragment=nav.slice(renderStart,renderEnd);
 try{for(const width of [320,390,1280]){const p=await browser.newPage({viewport:{width,height:800}}),errors=[],requests=[];p.on('pageerror',e=>errors.push(String(e)));await p.route('**/*',r=>{requests.push(r.request().url());return r.abort();});const tag=read('plateau.html').match(/<div class="piece-desc" id="piece-desc"[^>]*>/)[0];
 await p.setContent('<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"></head><body class="plateau-body"><div id="piece-image"></div>'+tag+'</div><input id="draft" value="Brouillon intact"><div id="scroll" style="height:80px;overflow:auto"><div style="height:400px">Repère</div></div></body></html>');await p.addStyleTag({content:read('style.css')});await p.addScriptTag({content:read('i18n/i18next.min.js')});await p.evaluate(()=>{window.RP_I18N_GAME_ENABLED=true;window.RPPlateauI18n={language:()=>i18next.language||'fr'};window.state={country:'soviet',currentCity:'qhs',currentBuilding:'qhs-prison',currentRoom:'entree_qhs',char:{name:'Fixture'},pa:7,arg:1234,inventory:[{id:'intact'}],progression:{step:3},_navigationServeur:true};window.calls=[];for(const n of ['fetch','sbRpc','sbRpcVerdict','deduireCoutOrdre','doOrder','commanderNavigationInterieure'])window[n]=(...a)=>{calls.push([n,...a]);throw Error('Appel métier interdit');};window.stable=()=>JSON.stringify({state,calls,draft:document.getElementById('draft').value,focus:document.activeElement.id,start:document.getElementById('draft').selectionStart,end:document.getElementById('draft').selectionEnd,scroll:document.getElementById('scroll').scrollTop});});
 for(const f of ['data.js','i18n/resources.js','i18n/room-resources.js','i18n/sovarka-descriptions-resources.js'])await p.addScriptTag({content:read(f)});
 await p.addScriptTag({content:fn(nav,'getBuildingContext')+'\n'+fn(nav,'piecesOrdonneesBatiment')+'\n'+fn(nav,'rpRefreshOpenRoomNames')+'\nwindow.RPRefreshOpenRoomNames=rpRefreshOpenRoomNames;\nfunction renderDescription(roomId){const buildingId="qhs-prison",b=BUILDINGS[buildingId],ctx=getBuildingContext(buildingId),room=Object.fromEntries(piecesOrdonneesBatiment(b,ctx))[roomId],roomOverride=ctx?.roomOverrides?.[roomId],isFirstRoom=Object.keys(b.rooms)[0]===roomId,estDansSaCellule=true;if(!room||ctx?.roomsExclues?.includes(roomId))throw Error("pièce inexistante");\n'+fragment+'\nreturn {source:descSourcePiece,rendered:displayDesc};}'});await p.addScriptTag({content:read('i18n/plateau-init.js')});
 for(const country of ['soviet','republic']){const cases=await p.evaluate(country=>{state.country=country;const b=BUILDINGS['qhs-prison'],ctx=getBuildingContext('qhs-prison');return piecesOrdonneesBatiment(b,ctx).filter(([id])=>!ctx?.roomsExclues?.includes(id)).map(([id])=>id);},country);assert.equal(cases.length,5);if(country==='soviet')assert.deepEqual(cases,proof.rooms.map(r=>r.id));
 for(const id of cases){const before=await p.evaluate(async id=>{await i18next.changeLanguage('en');state.currentRoom=id;const initial=renderDescription(id);document.getElementById('draft').focus();document.getElementById('draft').setSelectionRange(2,6);document.getElementById('scroll').scrollTop=50;return {initial,snapshot:stable()};},id);if(country==='soviet'){const r=proof.rooms.find(r=>r.id===id);assert.equal(before.initial.source,r.fr);assert.notEqual(before.initial.rendered,r.fr,'texte effectivement traduit dès le rendu');}
 for(const lang of langs){const got=await p.evaluate(async lang=>{await i18next.changeLanguage(lang);const node=document.getElementById('piece-desc');return {text:node.textContent,source:node.dataset.rpDescSource,expected:RPSovarkaDescI18n.desc(node.dataset.rpDescSource),dir:getComputedStyle(node).direction,snapshot:stable(),overflow:document.documentElement.scrollWidth>innerWidth,inside:node.scrollWidth<=node.clientWidth+1};},lang);assert.equal(got.snapshot,before.snapshot,country+'/'+id+'/'+lang);assert.equal(got.source,before.initial.source);assert.equal(got.text,got.expected);if(country==='republic'||lang==='fr')assert.equal(got.text,before.initial.source);else assert.notEqual(got.text,before.initial.source);assert.equal(got.dir,country==='soviet'&&lang==='ar'?'rtl':'ltr');assert.equal(got.overflow,false);assert.equal(got.inside,true);switches++;}
 }}assert.deepEqual(errors,[]);assert.deepEqual(requests,[]);await p.close();}}finally{await browser.close();}assert.equal(switches,270);console.log('270 bascules : cinq vraies pièces par pays, fragment de rendu de enterRoom et rafraîchissement existants.');
});
